SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.los, percentile_cont(0.75) within GROUP (ORDER BY i.los) AS q75 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'F' AND p.anchor_age = 55 AND p.anchor_year_group BETWEEN 50 AND 60 AND i.hadm_id IN (SELECT hadm_id FROM medications m WHERE m.drug_type = 'A') GROUP BY p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.los ORDER BY q75 NULLS LAST;